function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.menu').each(function () {
    const $menu = $(this);
    $menu.find('.menu-section').each(function () {
      const $section = $(this);
      const sectionTitleEl = $section.find('.menu-section-title');
      const section = sectionTitleEl.length ? cleanText(sectionTitleEl.text()) : null;

      $section.find('.menu-item').each(function () {
        const $item = $(this);

        // name
        const $titleEl = $item.find('.menu-item-title');
        const nameRaw = $titleEl.text();
        const name = cleanText(nameRaw);
        if (!name) return; // skip empty names

        // description
        const $descEl = $item.find('.menu-item-description');
        const description = $descEl.length ? cleanText($descEl.text()) : null;

        // price – take the first price element found (top or bottom)
        const $priceEl = $item.find('.menu-item-price-top, .menu-item-price-bottom').first();
        const priceText = $priceEl.length ? $priceEl.text() : '';
        const price = parsePrice(priceText);

        const item = { section, name, description, price };
        const key = `${item.section}|||${item.name}|||${item.description}|||${item.price}`;
        if (!seen.has(key)) {
          seen.add(key);
          items.push(item);
        }
      });
    });
  });

  return items;
}
